    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['clinic_id'] = Variable<String>(clinicId);
    map['drug_id'] = Variable<int>(drugId);
    map['quantity'] = Variable<int>(quantity);
    map['price'] = Variable<double>(price);
    map['date'] = Variable<DateTime>(date);
    if (!nullToAbsent || customer != null) {
      map['customer'] = Variable<String>(customer);
    }
    return map;
  }

  SalesCompanion toCompanion(bool nullToAbsent) {
    return SalesCompanion(
      id: Value(id),
      clinicId: Value(clinicId),
      drugId: Value(drugId),
      quantity: Value(quantity),
      price: Value(price),
      date: Value(date),
      customer: customer == null && nullToAbsent
          ? const Value.absent()
          : Value(customer),
    );
  }

  factory Sale.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Sale(
      id: serializer.fromJson<int>(json['id']),
      clinicId: serializer.fromJson<String>(json['clinicId']),
      drugId: serializer.fromJson<int>(json['drugId']),
      quantity: serializer.fromJson<int>(json['quantity']),
      price: serializer.fromJson<double>(json['price']),
      date: serializer.fromJson<DateTime>(json['date']),
      customer: serializer.fromJson<String?>(json['customer']),
    );
  }
