  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<int>(id),
      'clinicId': serializer.toJson<String>(clinicId),
      'drugId': serializer.toJson<int>(drugId),
      'quantity': serializer.toJson<int>(quantity),
      'price': serializer.toJson<double>(price),
      'date': serializer.toJson<DateTime>(date),
      'customer': serializer.toJson<String?>(customer),
    };
  }

  Sale copyWith({
    int? id,
    String? clinicId,
    int? drugId,
    int? quantity,
    double? price,
    DateTime? date,
    Value<String?> customer = const Value.absent(),
  }) => Sale(
    id: id ?? this.id,
    clinicId: clinicId ?? this.clinicId,
    drugId: drugId ?? this.drugId,
    quantity: quantity ?? this.quantity,
    price: price ?? this.price,
    date: date ?? this.date,
    customer: customer.present ? customer.value : this.customer,
  );
  Sale copyWithCompanion(SalesCompanion data) {
    return Sale(
      id: data.id.present ? data.id.value : this.id,
      clinicId: data.clinicId.present ? data.clinicId.value : this.clinicId,
      drugId: data.drugId.present ? data.drugId.value : this.drugId,
      quantity: data.quantity.present ? data.quantity.value : this.quantity,
      price: data.price.present ? data.price.value : this.price,
      date: data.date.present ? data.date.value : this.date,
      customer: data.customer.present ? data.customer.value : this.customer,
    );
